CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','user') NOT NULL DEFAULT 'user',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS assets (id CHAR(36) PRIMARY KEY,owner_id BIGINT UNSIGNED NOT NULL,original_name VARCHAR(255) NOT NULL,mime_type VARCHAR(120) NOT NULL,byte_size BIGINT UNSIGNED NOT NULL,sha256 CHAR(64) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(owner_id));